INSERT INTO `categories` (`category_id`, `category_name`, `description`) VALUES
(2, 'Fresh Vegetable', 'Locally sourced, seasonal vegetables harvested at peak freshness. Clean, crisp, and ideal for daily cooking and balanced meals.'),
(4, 'Exotic Vegetables', 'Premium, imported vegetables selected for superior quality and unique flavors. Perfect for gourmet recipes and international cuisines.'),
(5, 'Fresh Fruits', 'Naturally ripened, farm-fresh fruits packed with taste and nutrition. Carefully chosen to ensure sweetness, freshness, and quality.'),
(6, 'Exotic Fruits', 'Rare and imported fruits with exceptional flavor and texture. Handpicked for freshness and ideal for premium consumption.'),
(7, 'Salad Bowl', 'Freshly cut vegetables blended for nutrition and crunch. Ready-to-eat bowls designed for clean, healthy, and satisfying meals.'),
(8, 'Fruit Bowl', 'A refreshing mix of freshly cut fruits, balanced for taste and nutrition. Perfect for a light snack or a natural energy boost.'),
(9, 'Fresh Juice', 'Cold-pressed juices made from fresh fruits and vegetables. No preservatives, no added sugar—just pure, natural goodness.');
